CREATE OR REPLACE FUNCTION FNC_GETPOSFILARES_PRA
(
P_CODPROD IN NUMBER
) RETURN NUMBER AS
V_SEQRESERVA INT;
PRAGMA AUTONOMOUS_TRANSACTION;
BEGIN

SELECT (TRUNC(NVL(MAX(EST.AD_SEQRESERVA),0) / 100) * 100) + 100
INTO V_SEQRESERVA
FROM AD_VGFRESEST EST
WHERE EST.CODPROD = P_CODPROD;


RETURN V_SEQRESERVA;

--EXCEPTION WHEN OTHERS THEN

--RETURN 0;

END FNC_GETPOSFILARES_PRA;
/
